@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#101416;--panel:#171d1f;--panel-2:#1c2425;--line:#2a3333;--muted:#87918c;--text:#f0f1e9;--green:#b7d3a2;--green-dark:#263b32;--gold:#e5ba69;--gold-soft:#8c6b36;--square-light:#d9d4c3;--square-dark:#60786f;--font:'DM Sans',sans-serif;--display:'Manrope',sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--font);-webkit-font-smoothing:antialiased}body{min-height:100vh;background-image:radial-gradient(ellipse at 24% 40%,rgba(54,83,70,.15),transparent 42%),linear-gradient(130deg,#111617,#0e1213 70%)}button{font:inherit;color:inherit}button:focus-visible{outline:2px solid var(--green);outline-offset:3px}.app-shell{max-width:1450px;margin:0 auto;padding:0 56px 26px;min-height:100vh}.topbar{height:78px;border-bottom:1px solid rgba(220,230,220,.1);display:flex;align-items:center;justify-content:space-between;position:relative}.brand{font-family:var(--display);font-weight:800;letter-spacing:.13em;font-size:15px;color:#f4f3e8;text-decoration:none;display:flex;align-items:center;gap:11px}.brand-mark{font-size:23px;color:var(--gold);line-height:1}.brand-period,.title-period{color:var(--gold)}.top-center{position:absolute;left:50%;transform:translateX(-50%);font-size:9px;font-weight:700;letter-spacing:.17em;color:#9da59d;display:flex;align-items:center;gap:9px}.live-dot,.turn-dot{width:7px;height:7px;border-radius:100%;background:#a5c795;box-shadow:0 0 10px rgba(165,199,149,.4)}.top-divider{color:#48504a;margin:0 3px}.icon-button{width:30px;height:30px;border:1px solid #36403c;background:transparent;border-radius:50%;color:#b4beb4;cursor:pointer;font-size:14px}.icon-button:hover{border-color:var(--green);color:var(--green)}.game-layout{display:grid;grid-template-columns:minmax(460px,760px) minmax(290px,370px);justify-content:center;align-items:center;gap:clamp(46px,7vw,118px);max-width:1260px;margin:46px auto 0}.board-column{min-width:0}.board-topline,.player-row{display:flex;align-items:center;justify-content:space-between}.player-chip{display:flex;align-items:center;gap:10px;min-width:120px}.player-token{height:34px;width:34px;display:grid;place-items:center;border-radius:50%;font-size:21px}.black-token{background:#242d2b;color:#b8c2b9}.white-token{background:#e5e0d1;color:#58665d}.player-chip strong{display:block;font-family:var(--display);font-size:10px;letter-spacing:.14em}.player-chip small{display:block;color:#77827b;font-size:8px;letter-spacing:.16em;margin-top:3px}.turn-label{font-size:9px;font-weight:700;letter-spacing:.16em;color:#aab2a6;display:flex;gap:9px;align-items:center}.turn-label .turn-dot{width:6px;height:6px}.board-wrap{margin:19px auto 11px;max-width:760px}.board-frame{position:relative;padding:0 22px 21px 25px}.chess-stage{aspect-ratio:1;width:100%;overflow:hidden;border-radius:3px;position:relative;touch-action:none;background:radial-gradient(ellipse at 50% 42%,#283331,#17201f 75%);box-shadow:0 18px 70px rgba(0,0,0,.32);cursor:grab}.chess-stage:active{cursor:grabbing}.chess-stage canvas{display:block;width:100%;height:100%;touch-action:none;outline:none}.board-coords{position:absolute;color:#87938b;font-family:var(--display);font-size:9px;font-weight:700;letter-spacing:.05em}.coords-files{left:25px;right:22px;bottom:5px;display:flex;justify-content:space-around}.coords-ranks{top:0;bottom:21px;left:6px;display:flex;flex-direction:column;justify-content:space-around}.board-caption{display:flex;justify-content:center;gap:30px;font-size:8px;letter-spacing:.13em;font-weight:600;color:#758078;margin-top:8px}.board-caption i{font-style:normal;color:#acb9aa;font-size:12px;vertical-align:-1px;margin-right:5px}.player-row{padding:9px 0 0}.you-tag{margin-left:2px;border:1px solid #425443;color:#a8c198;padding:4px 7px;border-radius:3px;font-size:7px;font-weight:700;letter-spacing:.1em}.captured-strip{display:flex;align-items:center;gap:7px}.captured-label{font-size:8px;letter-spacing:.15em;color:#69736c}.captured-pieces{min-height:18px;display:flex;align-items:center;gap:1px;color:#b8c0b5;font-size:15px}.capture-divider{height:15px;width:1px;background:#323b37;margin:0 3px}.side-panel{padding-top:5px;max-width:370px}.panel-kicker{display:flex;align-items:center;gap:8px;font-size:8px;letter-spacing:.17em;font-weight:700;color:#94a593}.sparkle{font-size:13px;color:var(--gold)}h1{font-family:var(--display);font-weight:600;font-size:clamp(48px,5.3vw,67px);line-height:.98;letter-spacing:-.07em;margin:19px 0 15px}h1 em,.dialog h2 em{font-weight:500;color:var(--green);font-family:Georgia,serif;letter-spacing:-.06em}.intro-copy{font-size:13px;line-height:1.75;color:#9ba49b;max-width:330px;margin:0 0 20px}.power-callout{display:flex;align-items:center;gap:14px;padding:14px 15px;background:#19211f;border:1px solid #2a3930;border-radius:5px}.callout-icon{display:grid;place-items:center;width:34px;height:34px;flex:none;border-radius:4px;color:#b9d1a7;background:#283a30;font-size:21px}.power-callout strong{font-family:var(--display);font-size:9px;letter-spacing:.13em}.power-callout p{font-size:10px;color:#a1aaa0;margin:5px 0 0;line-height:1.45}.section-heading{display:flex;align-items:center;gap:10px;font-size:8px;font-weight:700;letter-spacing:.16em;color:#89948a;margin:23px 0 10px}.section-line{height:1px;flex:1;background:#2c3531}.king-card{display:flex;align-items:center;gap:11px;padding:10px 12px;border:1px solid #3c3323;border-radius:5px;background:linear-gradient(105deg,rgba(115,86,42,.16),rgba(29,31,26,.42))}.king-glyph{height:34px;width:34px;display:grid;place-items:center;color:#e9c36f;text-shadow:0 0 10px rgba(235,190,92,.35);font-size:25px}.king-copy{flex:1}.king-copy strong{display:block;font-family:var(--display);font-size:9px;letter-spacing:.1em;color:#e2c47f}.king-copy span{display:block;font-size:9px;color:#99958a;margin-top:4px}.gold-seal{color:#b48d4c;font-size:13px}.status-card{display:flex;align-items:center;gap:12px;padding:13px 14px;margin-top:17px;border-radius:5px;background:#1a2221;border:1px solid #2b3532;min-height:58px}.status-icon{width:27px;height:27px;display:grid;place-items:center;background:#2d3d31;border-radius:50%;color:#b7d3a2;font-size:13px;flex:none}.status-card strong{display:block;font-size:10px;font-weight:700;letter-spacing:.02em}.status-card span{display:block;font-size:9px;color:#929b92;margin-top:4px;line-height:1.4}.status-card.check{border-color:#735943;background:#29221c}.status-card.check .status-icon{background:#59402d;color:#eab874}.action-row{display:flex;gap:8px;margin-top:12px}.action-button{height:37px;padding:0 12px;border:1px solid #36403b;border-radius:4px;background:#1b2221;cursor:pointer;color:#c3cbc0;font-size:8px;font-weight:700;letter-spacing:.11em;display:flex;align-items:center;justify-content:center;gap:7px;transition:background .16s,border .16s,transform .16s}.action-button:hover:not(:disabled){background:#252f2c;border-color:#536558;transform:translateY(-1px)}.action-button:disabled{opacity:.42;cursor:not-allowed}.action-button span{font-size:15px;color:#b5c6ae}.primary-action{background:#b8d0a6;color:#172019;border-color:#b8d0a6;flex:1}.primary-action:hover:not(:disabled){background:#c9ddb9;border-color:#c9ddb9}.primary-action span{color:#243327}.square-action{width:38px;padding:0;font-size:19px}.move-history .section-heading{margin:22px 0 7px}.move-count-small{font-size:8px;color:#606b63;letter-spacing:.1em}.move-log{height:80px;overflow:auto;border-top:1px solid #252e2b;border-bottom:1px solid #252e2b;padding:6px 0;scrollbar-width:thin;scrollbar-color:#3a453e transparent}.empty-log{font-size:9px;color:#68736b;padding:14px 2px}.move-entry{display:grid;grid-template-columns:30px 1fr 1fr;align-items:center;padding:5px 7px;font-size:10px;border-radius:3px}.move-entry:nth-child(even){background:rgba(255,255,255,.025)}.move-number{color:#66716a;font-size:9px}.move-san{color:#e0e5da;font-weight:600}.move-san.recent{color:#c3dcae}.move-detail{font-size:8px;color:#96a78e;margin-left:4px}.panel-footer{border-top:1px solid #252e2b;margin-top:13px;padding-top:10px;display:flex;justify-content:space-between;color:#616c64;font-size:7px;letter-spacing:.14em;font-weight:700}.toast{position:fixed;left:50%;bottom:26px;transform:translate(-50%,20px);padding:11px 16px;background:#e4d7b6;color:#18201a;font-weight:700;font-size:11px;border-radius:4px;box-shadow:0 8px 30px #0008;opacity:0;pointer-events:none;transition:all .22s;z-index:5;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.dialog-backdrop{position:fixed;inset:0;background:rgba(5,9,9,.72);backdrop-filter:blur(8px);display:grid;place-items:center;padding:20px;z-index:10}.dialog-backdrop[hidden]{display:none}.dialog{width:min(440px,100%);background:#19201f;border:1px solid #35403a;padding:30px;border-radius:8px;position:relative;box-shadow:0 24px 80px #0009}.dialog-close{position:absolute;right:15px;top:12px;background:none;border:0;color:#9aa39a;font-size:25px;cursor:pointer}.dialog h2{font-family:var(--display);font-size:32px;line-height:1.1;letter-spacing:-.06em;margin:16px 0}.dialog p{font-size:12px;line-height:1.75;color:#a9b0a7}.dialog p strong{color:#e4c47d}.rules-done{margin-top:9px;width:100%}.promotion-options{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:20px}.promotion-option{background:#222a27;border:1px solid #3b4740;border-radius:5px;padding:13px 5px;color:#e9c36f;cursor:pointer}.promotion-option:hover{border-color:#c5d6b1;background:#2c3930}.promotion-option span{font-size:29px;display:block}.promotion-option small{display:block;color:#b8c1b6;font-size:8px;letter-spacing:.1em;margin-top:6px}
@media(max-width:1050px){.app-shell{padding-left:34px;padding-right:34px}.game-layout{gap:45px;grid-template-columns:minmax(420px,620px) minmax(280px,340px);margin-top:42px}.side-panel{width:100%}.intro-copy{font-size:12px}}
@media(max-width:800px){.app-shell{padding:0 20px 24px}.topbar{height:64px}.game-layout{display:flex;flex-direction:column;align-items:stretch;gap:25px;margin:25px auto 0;max-width:620px}.board-column{width:100%}.side-panel{max-width:none;padding:0 2px}.board-wrap{margin-top:14px}.board-frame{padding:0 17px 18px 20px}.coords-files{left:20px;right:17px;bottom:4px}.coords-ranks{bottom:18px;left:5px}.player-token{width:30px;height:30px;font-size:18px}.player-chip{min-width:105px}.side-panel h1{font-size:47px;margin:13px 0 10px}.intro-copy{max-width:460px;margin-bottom:15px}.section-heading{margin-top:17px}.king-card{padding:8px 11px}.status-card{margin-top:12px}.move-history .section-heading{margin-top:16px}.move-log{height:66px}.panel-footer{margin-bottom:3px}.top-center{font-size:8px}}
@media(max-width:430px){.app-shell{padding-left:14px;padding-right:14px}.topbar{height:58px}.top-center{left:auto;right:42px;transform:none;gap:6px;font-size:7px}.brand{font-size:13px;gap:7px}.brand-mark{font-size:20px}.help-button{width:27px;height:27px}.game-layout{margin-top:19px;gap:19px}.board-frame{padding-left:17px;padding-right:14px;padding-bottom:16px}.coords-files{left:17px;right:14px}.coords-ranks{bottom:16px}.board-caption{font-size:7px;gap:18px}.player-chip{min-width:auto}.player-chip strong{font-size:9px}.player-chip small{font-size:7px}.you-tag{font-size:6px;padding:3px 5px}.captured-strip{gap:5px}.captured-label{font-size:7px}.captured-pieces{font-size:13px}.side-panel h1{font-size:43px}.intro-copy{font-size:11px;line-height:1.55}.power-callout{padding:10px}.power-callout p{font-size:9px}.section-heading{font-size:7px;margin:14px 0 8px}.king-card{padding:7px 10px}.status-card{min-height:52px;padding:10px 11px}.action-button{height:35px;padding:0 8px;font-size:7px}.action-row{gap:6px}.move-log{height:60px}.dialog{padding:25px 22px}.toast{bottom:16px}}
@media(orientation:landscape) and (max-height:620px) and (max-width:950px){.game-layout{display:grid;grid-template-columns:minmax(300px,52vh) minmax(250px,1fr);gap:24px;margin-top:16px;align-items:center}.board-frame{padding:0 15px 15px 18px}.board-wrap{margin:8px 0}.board-caption{margin-top:2px}.side-panel h1{font-size:39px;margin:9px 0}.intro-copy{margin-bottom:10px}.section-heading{margin-top:10px}.move-history .section-heading{margin-top:12px}.move-log{height:50px}.app-shell{padding-bottom:10px}.player-row{padding-top:2px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';
import { OrbitControls } from 'https://cdn.jsdelivr.net/npm/three@0.169.0/examples/jsm/controls/OrbitControls.js';

const $ = (id) => document.getElementById(id);
const stage = $('chess-stage');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#17201f');
const camera = new THREE.PerspectiveCamera(35, 1, .1, 100);
camera.position.set(7.5, 9.5, 11.8);
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
stage.appendChild(renderer.domElement);
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, .1, 0);
controls.enableDamping = true;
controls.dampingFactor = .075;
controls.minDistance = 9;
controls.maxDistance = 19;
controls.maxPolarAngle = Math.PI * .46;
controls.minPolarAngle = .18;
controls.rotateSpeed = .55;
controls.enablePan = false;
scene.add(new THREE.HemisphereLight('#e7eee0', '#263431', 2.0));
const keyLight = new THREE.DirectionalLight('#fff0ce', 3.2);
keyLight.position.set(-5, 11, 6);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(1024, 1024);
keyLight.shadow.camera.left = -8; keyLight.shadow.camera.right = 8; keyLight.shadow.camera.top = 8; keyLight.shadow.camera.bottom = -8;
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight('#a9c5bd', 1.15);
fillLight.position.set(7, 7, -6); scene.add(fillLight);
const boardGroup = new THREE.Group(); scene.add(boardGroup);
const pieceGroup = new THREE.Group(); scene.add(pieceGroup);
const markerGroup = new THREE.Group(); scene.add(markerGroup);
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
const squareMeshes = [];
let selected = null;
let legalTargets = [];
let flipped = false;
let lastMove = null;
let toastTimer;
let pendingPromotion = null;
let checkSquare = null;

function resize() {
  const w = Math.max(1, stage.clientWidth), h = Math.max(1, stage.clientHeight);
  renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
}
new ResizeObserver(resize).observe(stage); resize();

function mat(color, roughness = .42, metalness = .08) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness });
}
const squareMats = [mat('#d9d4c3', .78, 0), mat('#60786f', .78, 0)];
const boardWood = mat('#293631', .35, .18);
const ivoryMat = mat('#efe5cf', .28, .12);
const darkMat = mat('#25302f', .27, .3);
const goldMat = new THREE.MeshStandardMaterial({ color: '#e5bc69', roughness: .23, metalness: .74, emissive: '#7c5421', emissiveIntensity: .12 });
const whiteAccent = mat('#c8b992', .3, .28);
const darkAccent = mat('#687973', .3, .36);
const boardGeometry = new THREE.BoxGeometry(1, .12, 1);
const markerGeometry = new THREE.PlaneGeometry(.92, .92);
const markerMaterial = new THREE.MeshBasicMaterial({ color: '#b5e08f', transparent: true, opacity: .31, depthWrite: false, side: THREE.DoubleSide });
const selectedMaterial = new THREE.MeshBasicMaterial({ color: '#e7ca78', transparent: true, opacity: .38, depthWrite: false, side: THREE.DoubleSide });
const lastMaterial = new THREE.MeshBasicMaterial({ color: '#e7bd60', transparent: true, opacity: .24, depthWrite: false, depthTest: false, side: THREE.DoubleSide });
const checkMaterial = new THREE.MeshBasicMaterial({ color: '#df7159', transparent: true, opacity: .4, depthWrite: false, side: THREE.DoubleSide });
const dotGeometry = new THREE.CircleGeometry(.15, 24);
const dotMaterial = new THREE.MeshBasicMaterial({ color: '#f0f3db', transparent: true, opacity: .8 });
const captureRingGeometry = new THREE.RingGeometry(.34, .43, 36);
const captureRingMaterial = new THREE.MeshBasicMaterial({ color: '#f2d18a', transparent: true, opacity: .9, side: THREE.DoubleSide });

function posOf(file, rank) { return [file - 3.5, .2, 3.5 - rank]; }
function makeBoard() {
  const frame = new THREE.Mesh(new THREE.BoxGeometry(8.36, .34, 8.36), boardWood);
  frame.position.set(0, -.055, 0); frame.receiveShadow = true; frame.castShadow = true; boardGroup.add(frame);
  const trim = new THREE.Mesh(new THREE.BoxGeometry(8.46, .10, 8.46), mat('#493c29', .3, .38));
  trim.position.y = -.225; boardGroup.add(trim);
  for (let rank = 0; rank < 8; rank++) for (let file = 0; file < 8; file++) {
    const mesh = new THREE.Mesh(boardGeometry, squareMats[(file + rank) % 2]);
    mesh.position.set(file - 3.5, .13, 3.5 - rank); mesh.receiveShadow = true;
    mesh.userData.square = { file, rank }; boardGroup.add(mesh); squareMeshes.push(mesh);
  }
  const floor = new THREE.Mesh(new THREE.CircleGeometry(200, 64), new THREE.MeshBasicMaterial({ color: '#17201f' }));
  floor.rotation.x = -Math.PI / 2; floor.position.y = -.27; scene.add(floor);
}
makeBoard();

function mesh(geometry, material, group, x, y, z, sx = 1, sy = 1, sz = 1) {
  const m = new THREE.Mesh(geometry, material); m.position.set(x, y, z); m.scale.set(sx, sy, sz); m.castShadow = true; m.receiveShadow = true; group.add(m); return m;
}
function cylinder(rt, rb, h, material, group, x, y, z, segments = 32) {
  return mesh(new THREE.CylinderGeometry(rt, rb, h, segments), material, group, x, y, z);
}
function sphere(r, material, group, x, y, z, sx = 1, sy = 1, sz = 1) {
  return mesh(new THREE.SphereGeometry(r, 24, 16), material, group, x, y, z, sx, sy, sz);
}
function buildPiece(piece, file, rank) {
  const root = new THREE.Group(); root.position.set(file - 3.5, .19, 3.5 - rank);
  root.userData.square = { file, rank }; root.userData.piece = piece;
  const royal = piece.royal;
  const baseMat = royal ? goldMat : piece.color === 'w' ? ivoryMat : darkMat;
  const accent = royal ? goldMat : piece.color === 'w' ? whiteAccent : darkAccent;
  const scale = piece.type === 'king' || royal ? 1 : .9;
  const g = new THREE.Group(); g.scale.setScalar(scale); root.add(g);
  cylinder(.36, .39, .13, baseMat, g, 0, .065, 0);
  cylinder(.28, .35, .10, accent, g, 0, .17, 0);
  cylinder(.22, .26, .12, baseMat, g, 0, .27, 0);
  const collarY = .35;
  if (piece.type === 'pawn' && !royal) {
    cylinder(.19, .23, .28, baseMat, g, 0, .48, 0);
    sphere(.2, accent, g, 0, .72, 0, 1, 1.05, 1);
    sphere(.105, piece.color === 'w' ? ivoryMat : darkMat, g, 0, .74, .145, .72, .82, .72);
  } else if (piece.type === 'rook' && !royal) {
    cylinder(.22, .17, .45, baseMat, g, 0, .58, 0);
    cylinder(.27, .21, .11, accent, g, 0, .84, 0);
    cylinder(.22, .24, .12, baseMat, g, 0, .95, 0);
    for (let i = 0; i < 4; i++) { const a = i * Math.PI / 2; mesh(new THREE.BoxGeometry(.12, .14, .12), accent, g, Math.cos(a) * .17, 1.06, Math.sin(a) * .17); }
  } else if (piece.type === 'knight' && !royal) {
    cylinder(.19, .16, .40, baseMat, g, 0, .55, 0);
    sphere(.22, accent, g, 0, .78, -.015, .8, 1.15, .76);
    // Sculpted horse head, muzzle, ears and mane.
    sphere(.145, baseMat, g, .025, .96, .02, .78, 1.25, .75);
    sphere(.11, baseMat, g, .045, 1.04, -.11, .8, .8, 1.3);
    sphere(.09, accent, g, .06, .94, .12, .85, 1.1, .75);
    mesh(new THREE.ConeGeometry(.072, .22, 4), baseMat, g, -.055, 1.18, -.015, 1, 1, 1);
    sphere(.028, royal ? goldMat : piece.color === 'w' ? darkMat : ivoryMat, g, .11, 1.02, .06);
  } else if (piece.type === 'bishop' && !royal) {
    cylinder(.19, .16, .42, baseMat, g, 0, .56, 0);
    sphere(.18, accent, g, 0, .84, 0, .82, 1.15, .82);
    sphere(.09, baseMat, g, 0, 1.01, 0);
    mesh(new THREE.ConeGeometry(.035, .26, 12), accent, g, 0, 1.20, 0);
    const slash = mesh(new THREE.BoxGeometry(.045, .18, .045), piece.color === 'w' ? darkAccent : ivoryMat, g, .06, .86, .08); slash.rotation.z = -.48;
  } else if (piece.type === 'queen' && !royal) {
    cylinder(.19, .16, .42, baseMat, g, 0, .56, 0);
    sphere(.20, accent, g, 0, .83, 0, 1.1, .66, 1.1);
    cylinder(.19, .22, .10, baseMat, g, 0, .98, 0);
    for (let i = 0; i < 5; i++) { const a = (i / 5) * Math.PI * 2; sphere(.065, accent, g, Math.cos(a) * .17, 1.12 + (i % 2) * .07, Math.sin(a) * .17); }
    sphere(.08, accent, g, 0, 1.22, 0);
  } else {
    // The crowned king stays royal gold, even after inheriting a movement power.
    cylinder(.20, .16, .45, baseMat, g, 0, .57, 0);
    sphere(.20, accent, g, 0, .87, 0, 1.15, .62, 1.15);
    cylinder(.20, .23, .1, baseMat, g, 0, 1.0, 0);
    cylinder(.13, .16, .16, accent, g, 0, 1.10, 0);
    cylinder(.035, .035, .25, goldMat, g, 0, 1.31, 0, 12);
